# aplicar
ch=0
for k,v in src.items():
    if not isinstance(v,str) or not v.strip(): continue
    if d.get(k)!=v: continue  # ya traducido
    if k.endswith(".flavor") and v in FLAV: d[k]=FLAV[v]; ch+=1
    elif v in FLAV: d[k]=FLAV[v]; ch+=1
    elif k in ov: d[k]=ov[k]; ch+=1
json.dump(d, open(M+"/esp/relics.json","w",encoding="utf-8"), ensure_ascii=False, indent=2)
print("relics aplicados:", ch)
